using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MyDoc.Data;using MyDoc.Models;using MyDoc.Services;
namespace MyDoc.Pages.Documents;[Authorize]public sealed class EditModel(DocSpaceDbContext db,ICurrentUserService users,IDocumentAuthorizationService auth,IHtmlSafetyService safety):PageModel{public Document?Document{get;private set;}public ApplicationUser?CurrentUser{get;private set;}public DocumentAccess Access{get;private set;}public bool CanEdit=>Access is DocumentAccess.Owner or DocumentAccess.Editor;public bool IsOwner=>Access==DocumentAccess.Owner;public async Task<IActionResult>OnGetAsync(int id,CancellationToken ct){if(!await Load(id,ct))return NotFound();return Page();}async Task<bool>Load(int id,CancellationToken ct){CurrentUser=await users.GetCurrentAsync(User);if(CurrentUser is null)return false;Access=await auth.GetAccessAsync(id,CurrentUser.Id,ct);if(Access==DocumentAccess.None)return false;Document=await db.Documents.Include(x=>x.Owner).Include(x=>x.Shares).ThenInclude(x=>x.User).FirstOrDefaultAsync(x=>x.Id==id,ct);return Document is not null;}public async Task<IActionResult>OnPostSaveAsync(int id,string title,string contentHtml,CancellationToken ct){var user=await users.GetCurrentAsync(User);if(user is null)return Challenge();var access=await auth.GetAccessAsync(id,user.Id,ct);if(access is not(DocumentAccess.Owner or DocumentAccess.Editor))return Forbid();if(string.IsNullOrWhiteSpace(title)||title.Trim().Length>200)return BadRequest(new{error="A title of 1–200 characters is required."});var doc=await db.Documents.FindAsync([id],ct);if(doc is null)return NotFound();var clean=safety.Sanitize(contentHtml);if(doc.Title==title.Trim()&&doc.ContentHtml==clean)return new JsonResult(new{savedAt=doc.UpdatedAtUtc,unchanged=true});var version=await db.DocumentVersions.Where(v=>v.DocumentId==id).MaxAsync(v=>(int?)v.VersionNumber,ct)??0;db.DocumentVersions.Add(new DocumentVersion{DocumentId=id,VersionNumber=version+1,Title=doc.Title,ContentHtml=doc.ContentHtml,CreatedByUserId=user.Id,CreatedAtUtc=DateTime.UtcNow});doc.Title=title.Trim();doc.ContentHtml=clean;doc.UpdatedAtUtc=DateTime.UtcNow;await db.SaveChangesAsync(ct);return new JsonResult(new{savedAt=doc.UpdatedAtUtc});}public async Task<IActionResult>OnPostShareAsync(int id,string email,SharePermission permission,CancellationToken ct){var me=await users.GetCurrentAsync(User);if(me is null)return Challenge();if(await auth.GetAccessAsync(id,me.Id,ct)!=DocumentAccess.Owner)return Forbid();var normalized=email.Trim().ToUpperInvariant();var target=await db.Users.FirstOrDefaultAsync(u=>u.NormalizedEmail==normalized,ct);if(target is null||target.Id==me.Id){TempData["Error"]=target is null?"No registered account matches that email.":"You already own this document.";return RedirectToPage(new{id});}var share=await db.DocumentShares.FirstOrDefaultAsync(s=>s.DocumentId==id&&s.UserId==target.Id,ct);if(share is null)db.DocumentShares.Add(new DocumentShare{DocumentId=id,UserId=target.Id,Permission=permission});else share.Permission=permission;await db.SaveChangesAsync(ct);TempData["Success"]=$"Sharing saved for {target.Email}.";return RedirectToPage(new{id});}public async Task<IActionResult>OnPostRevokeAsync(int id,int userId,CancellationToken ct){var me=await users.GetCurrentAsync(User);if(me is null)return Challenge();if(await auth.GetAccessAsync(id,me.Id,ct)!=DocumentAccess.Owner)return Forbid();var share=await db.DocumentShares.FirstOrDefaultAsync(s=>s.DocumentId==id&&s.UserId==userId,ct);if(share is not null){db.DocumentShares.Remove(share);await db.SaveChangesAsync(ct);}return RedirectToPage(new{id});}public async Task<IActionResult>OnGetVersionsAsync(int id,CancellationToken ct){if(!await Load(id,ct))return NotFound();var versions=await db.DocumentVersions.Include(v=>v.CreatedByUser).Where(v=>v.DocumentId==id).OrderByDescending(v=>v.VersionNumber).ToListAsync(ct);return new JsonResult(versions.Select(v=>new{v.Id,v.VersionNumber,v.Title,v.CreatedAtUtc,author=v.CreatedByUser.FullName}));}public async Task<IActionResult>OnPostRestoreAsync(int id,int versionId,CancellationToken ct){var me=await users.GetCurrentAsync(User);if(me is null)return Challenge();if(await auth.GetAccessAsync(id,me.Id,ct) is not(DocumentAccess.Owner or DocumentAccess.Editor))return Forbid();var version=await db.DocumentVersions.FirstOrDefaultAsync(v=>v.Id==versionId&&v.DocumentId==id,ct);var doc=await db.Documents.FindAsync([id],ct);if(version is null||doc is null)return NotFound();var number=(await db.DocumentVersions.Where(v=>v.DocumentId==id).MaxAsync(v=>(int?)v.VersionNumber,ct)??0)+1;db.DocumentVersions.Add(new DocumentVersion{DocumentId=id,VersionNumber=number,Title=doc.Title,ContentHtml=doc.ContentHtml,CreatedByUserId=me.Id,CreatedAtUtc=DateTime.UtcNow});doc.Title=version.Title;doc.ContentHtml=version.ContentHtml;doc.UpdatedAtUtc=DateTime.UtcNow;await db.SaveChangesAsync(ct);TempData["Success"]="Version restored; the prior state was retained in history.";return RedirectToPage(new{id});}}
